from vibe_agent.fixer.fix_suggestion import FixSuggestion
from vibe_agent.fixer.files import is_secret

MAX_EDITS = 5

# never let the LLM edit these: they're generated by package managers
LOCKFILES = ["package-lock.json", "pnpm-lock.yaml", "yarn.lock",
             "bun.lock", "bun.lockb", "uv.lock", "poetry.lock"]

# the BuildPlan fields a "plan" fix is allowed to change
PLAN_FIELDS = ["framework", "runtime_version", "package_manager", "install_command",
               "build_command", "start_command", "output_dir", "port"]


def check_fix(fix: FixSuggestion, files:list[str], file_contents: dict[str, str]) -> None:
    if len(fix.edits) > MAX_EDITS:
        raise ValueError(f"Fix has {len(fix.edits)} edits (max {MAX_EDITS})")

            # 2. check every edit before we let it near the user's code
    for edit in fix.edits:
        name = edit.file.split("/")[-1]      # "frontend/package-lock.json" → "package-lock.json"

        # the file must really exist in the project
        if edit.file not in files:
            raise ValueError(f"Fix edits a file that doesn't exist: {edit.file}")

        # never touch secrets or lockfiles
        if is_secret(edit.file) or name in LOCKFILES:
            raise ValueError(f"Fix tries to edit a protected file: {edit.file}")

        # we can only verify edits to files we actually showed the LLM
        if edit.file not in file_contents:
            raise ValueError(f"Fix edits a file the LLM never saw: {edit.file}")

        # the "find" text must appear exactly once
        count = file_contents[edit.file].count(edit.find)
        if count != 1:
            raise ValueError(f"'find' text appears {count} times in {edit.file} (must be exactly 1)")

    for field in fix.plan_changes:
        if field not in PLAN_FIELDS:
            raise ValueError (f"Fix tries to change an unknown or protected plan field: {field}")